                            t.HasCheckConstraint("ck_orders_long_only", "(order_leg_type = 'ENTRY') = (txn_type = 'B')");

                            t.HasCheckConstraint("ck_orders_mandatory_sl_target", "stop_loss_price > 0 AND target_sell_price > stop_loss_price");

