                            t.HasCheckConstraint("ck_orders_order_type", "order_type IN ('LMT', 'SL')");

                            t.HasCheckConstraint("ck_orders_parent_link", "(order_leg_type = 'ENTRY') = (parent_order_id IS NULL)");

                            t.HasCheckConstraint("ck_orders_prices", "price > 0 AND order_ltp > 0 AND (avg_fill_price IS NULL OR avg_fill_price > 0)");

                            t.HasCheckConstraint("ck_orders_product", "product IN ('I', 'M', 'B')");

                            t.HasCheckConstraint("ck_orders_quantity", "quantity > 0 AND filled_quantity >= 0 AND filled_quantity <= quantity");

                            t.HasCheckConstraint("ck_orders_rejection_reason", "status NOT IN ('REJECTED', 'FAILED') OR rejection_reason IS NOT NULL");

                            t.HasCheckConstraint("ck_orders_segment", "segment IN ('D', 'E')");

                            t.HasCheckConstraint("ck_orders_sl_trigger", "order_type <> 'SL' OR (trigger_price IS NOT NULL AND trigger_price > 0 AND (txn_type <> 'S' OR price <= trigger_price) AND (txn_type <> 'B' OR price >= trigger_price))");

                            t.HasCheckConstraint("ck_orders_status", "status IN ('PENDING', 'PLACED', 'OPEN', 'TRIGGER_PENDING', 'PARTIALLY_FILLED', 'FILLED', 'CANCELLED', 'REJECTED', 'FAILED')");

                            t.HasCheckConstraint("ck_orders_trade_mode", "trade_mode IN ('PAPER', 'REAL')");

                            t.HasCheckConstraint("ck_orders_txn_type", "txn_type IN ('B', 'S')");
                        });
