                        .HasMaxLength(500)
                        .HasColumnType("character varying(500)")
                        .HasColumnName("rejection_reason");

                    b.Property<decimal>("RiskRewardRatio")
                        .ValueGeneratedOnAddOrUpdate()
                        .HasPrecision(9, 4)
                        .HasColumnType("numeric(9,4)")
                        .HasColumnName("risk_reward_ratio")
                        .HasComputedColumnSql("COALESCE(ROUND(CASE WHEN signal_type = 'BUY' THEN (mandatory_target_price - entry_option_ltp) / NULLIF(entry_option_ltp - mandatory_sl_price, 0) ELSE (entry_option_ltp - mandatory_target_price) / NULLIF(mandatory_sl_price - entry_option_ltp, 0) END, 4), 0)", true);

                    b.Property<long>("SecurityId")
                        .HasColumnType("bigint")
                        .HasColumnName("security_id");

                    b.Property<string>("SignalType")
                        .IsRequired()
                        .HasMaxLength(4)
                        .HasColumnType("character varying(4)")
                        .HasColumnName("signal_type");

                    b.Property<string>("SlMethod")
                        .IsRequired()
                        .HasMaxLength(18)
                        .HasColumnType("character varying(18)")
                        .HasColumnName("sl_method");

                    b.Property<decimal>("SpotPrice")
                        .HasPrecision(18, 2)
                        .HasColumnType("numeric(18,2)")
                        .HasColumnName("spot_price");

                    b.Property<string>("Status")
                        .IsRequired()
                        .HasMaxLength(10)
                        .HasColumnType("character varying(10)")
                        .HasColumnName("status");

                    b.Property<DateOnly>("TradingDate")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("date")
                        .HasColumnName("trading_date")
                        .HasDefaultValueSql("(now() AT TIME ZONE 'Asia/Kolkata')::date");

                    b.HasKey("SignalId")
                        .HasName("pk_signals");

                    b.HasIndex("DetectionId")
                        .HasDatabaseName("ix_signals_detection_id");

                    b.HasIndex("InstrumentId")
                        .HasDatabaseName("ix_signals_instrument_id");

                    b.HasIndex("NewsId")
                        .HasDatabaseName("ix_signals_news_id");

                    b.HasIndex("SecurityId")
                        .HasDatabaseName("ix_signals_security_id");

                    b.HasIndex("TradingDate", "Status")
                        .HasDatabaseName("ix_signals_trading_date_status");

                    b.ToTable("signals", "trn", t =>
                        {
                            t.HasCheckConstraint("ck_signals_mandatory_sl_target", "entry_option_ltp > 0 AND mandatory_sl_price > 0 AND mandatory_target_price > 0 AND ((signal_type = 'BUY' AND mandatory_sl_price < entry_option_ltp AND entry_option_ltp < mandatory_target_price) OR (signal_type = 'SELL' AND mandatory_target_price < entry_option_ltp AND entry_option_ltp < mandatory_sl_price))");

                            t.HasCheckConstraint("ck_signals_rejection_reason", "status <> 'REJECTED' OR rejection_reason IS NOT NULL");

                            t.HasCheckConstraint("ck_signals_risk_reward_positive", "risk_reward_ratio > 0");

                            t.HasCheckConstraint("ck_signals_scores", "pattern_score BETWEEN 0 AND 100 AND news_score BETWEEN 0 AND 100 AND oi_greeks_score BETWEEN 0 AND 100 AND combined_ai_confidence BETWEEN 0 AND 100");

                            t.HasCheckConstraint("ck_signals_signal_type", "signal_type IN ('BUY', 'SELL')");

                            t.HasCheckConstraint("ck_signals_sl_method", "sl_method IN ('STRUCTURAL', 'FIXED_PCT_FALLBACK')");

                            t.HasCheckConstraint("ck_signals_status", "status IN ('NEW', 'DISPATCHED', 'REJECTED', 'EXPIRED')");
                        });
                });

